	// Flows Policy flows of the proxy, in execution order, run after the flows of the plan the request matched.
	// The manifest owns them: on every apply the proxy's flows are replaced by the declared ones, so a
	// flow authored in the policy studio survives only if the manifest carries it, and omitting `flows`
	// removes them all. Each step's configuration is validated against its policy's schema, on apply and
	// on dry run, and reported back as stored.
	//
	//
	// Examples: [{"name":"Tools ACL","request":[{"configuration":{"authorizations":[{"authorizedFeatures":[{"methods":["TOOLS_LIST","TOOLS_CALL"],"patternType":"ANY","type":"TOOLS"}]}]},"name":"MCP ACL","policy":"mcp-acl"}],"selectors":[{"methods":["tools/list","tools/call"],"type":"MCP"}]}]
